/**
 * Independent ephemeris + frame validation against JPL SPICE.
 *
 * Reference data (tests/data/frame-reference.json) is generated by
 * scripts/generate-frame-constants.py using spiceypy with DE421 +
 * moon_pa_de421_1900-2050.bpc + moon_080317.tf + pck00008.tpc. The IAU_MOON frame
 * is evaluated by SPICE from the PCK (independent of astronomy-engine). Conventions:
 * planetocentric latitude, east-positive longitude, azimuth from north toward east.
 *
 * Tolerances are fixed engineering bounds, NOT tuned to make the app pass. Measured
 * maxima (9 epochs 2026-06..2027-06 x 6 sites incl. exact/near pole):
 *   Sun elevation 0.000576 deg, Earth elevation 0.000246 deg, azimuth 0.007181 deg,
 *   IAU frame angle 0.001028 deg, sub-Earth point 0.006173 deg.
 */
import { describe, expect, it } from 'vitest';
import * as A from 'astronomy-engine';
import { computeEphemeris, moonBodyFrame } from '../src/engine/ephemeris';
import { classifyFrame, convertSite, frameResidualDeg } from '../src/engine/lunarFrame';
import ref from './data/frame-reference.json';

const TOL = { sunEl: 0.01, earthEl: 0.01, az: 0.02, subEarth: 0.01, frame: 0.002, convert: 0.002 };
const wrap180 = (d: number) => { const w = ((d % 360) + 360) % 360; return w > 180 ? w - 360 : w; };

function appFrameMatrix(t: number): number[] {
  const f = moonBodyFrame(new A.AstroTime(new Date(t)));
  return [f.x.x, f.y.x, f.z.x, f.x.y, f.y.y, f.z.y, f.x.z, f.y.z, f.z.z];
}
function rotationAngleDeg(R: number[], M: number[]): number {
  let tr = 0;
  for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
    let s = 0; for (let k = 0; k < 3; k++) s += R[i * 3 + k] * M[j * 3 + k];
    if (i === j) tr += s;
  }
  return (Math.acos(Math.max(-1, Math.min(1, (tr - 1) / 2))) * 180) / Math.PI;
}
const siteFor = (s: { name: string; lat: number; lon: number; elev_m: number }) => ({
  id: s.name, latitude: s.lat, longitude: s.lon, elevationM: s.elev_m,
  terrain: { elevations: [0], resolutionDeg: 1 },
});

describe('ephemeris vs SPICE (independent)', () => {
  for (const ep of ref.epochs) {
    it(`Sun/Earth az+el at ${ep.iso}`, () => {
      const t = Date.parse(ep.iso + 'Z');
      for (const s of ep.sites) {
        const e = computeEphemeris(siteFor(s) as never, t);
        expect(Math.abs(e.sun.elevationDeg - s.sun_el), `Sun el ${s.name}`).toBeLessThan(TOL.sunEl);
        expect(Math.abs(e.earth.elevationDeg - s.earth_el), `Earth el ${s.name}`).toBeLessThan(TOL.earthEl);
        expect(Math.abs(wrap180(e.sun.azimuthDeg - s.sun_az)), `Sun az ${s.name}`).toBeLessThan(TOL.az);
        expect(Math.abs(wrap180(e.earth.azimuthDeg - s.earth_az)), `Earth az ${s.name}`).toBeLessThan(TOL.az);
      }
    });

    it(`IAU frame + sub-Earth point at ${ep.iso}`, () => {
      const t = Date.parse(ep.iso + 'Z');
      const ang = rotationAngleDeg(appFrameMatrix(t), ep.iau_to_j2000);
      expect(ang, 'IAU frame angle vs SPICE').toBeLessThan(TOL.frame);
      const e = computeEphemeris(siteFor({ name: 'x', lat: -89.9, lon: 0, elev_m: 0 }) as never, t);
      expect(Math.abs(e.libration.subEarthLatitudeDeg - ep.subearth_iau.lat)).toBeLessThan(TOL.subEarth);
      expect(Math.abs(wrap180(e.libration.subEarthLongitudeDeg - ep.subearth_iau.lon))).toBeLessThan(TOL.subEarth);
    });
  }
});

describe('frame conversion (constant ME->IAU vs SPICE exact)', () => {
  it('shipped constant rotation matches SPICE exact conversion within the disclosed residual', () => {
    // Two rotations differing by angle theta move any unit vector by at most theta,
    // so the constant-vs-exact POSITION separation is bounded by the frame residual
    // (~0.0039 deg). Raw longitude is amplified by 1/cos(lat) near the pole and is
    // the wrong metric there; angular separation is the physically meaningful bound.
    const sepDeg = (la1: number, lo1: number, la2: number, lo2: number) => {
      const v = (la: number, lo: number) => {
        const a = (la * Math.PI) / 180, b = (lo * Math.PI) / 180;
        return [Math.cos(a) * Math.cos(b), Math.cos(a) * Math.sin(b), Math.sin(a)];
      };
      const p = v(la1, lo1), q = v(la2, lo2);
      const d = p[0] * q[0] + p[1] * q[1] + p[2] * q[2];
      return (Math.acos(Math.max(-1, Math.min(1, d))) * 180) / Math.PI;
    };
    const bound = frameResidualDeg('me') * 1.3; // disclosed residual + small margin
    for (const c of ref.conversions) {
      const conv = convertSite(c.me_lat, c.me_lon, 'me');
      // TS must reproduce the Python constant-matrix conversion.
      expect(Math.abs(conv.latitude - c.constant.latitude), c.name).toBeLessThan(1e-4);
      expect(Math.abs(wrap180(conv.longitude - c.constant.longitude)), c.name).toBeLessThan(1e-4);
      // Constant approximation vs exact SPICE rotation, as angular position separation.
      const sep = sepDeg(conv.latitude, conv.longitude, c.exact_at_ref.latitude, c.exact_at_ref.longitude);
      expect(sep, `${c.name} position separation`).toBeLessThan(bound);
    }
  });

  it('classifies known frames and discloses residuals; blocks unknown frames', () => {
    expect(classifyFrame('MOON_ME').recognized).toBe(true);
    expect(classifyFrame('MOON_ME_DE421').transform).toBe('me');
    // Real LOLA product frame string carries a parenthetical ephemeris qualifier.
    expect(classifyFrame('MOON_ME (JPL DE421)').transform).toBe('me');
    expect(classifyFrame('MOON_PA (JPL DE421)').transform).toBe('pa');
    expect(classifyFrame('MOON_PA').transform).toBe('pa');
    expect(classifyFrame('IAU_MOON').transform).toBe('iau');
    expect(classifyFrame('MysteryFrame').recognized).toBe(false);
    expect(classifyFrame(undefined).recognized).toBe(false);
    // A bare "ME"/"PA" substring inside an unrelated word must NOT be recognized.
    expect(classifyFrame('MysteryFrame').transform).toBeNull();
    expect(frameResidualDeg('me')).toBeGreaterThan(0);
    expect(frameResidualDeg('me')).toBeLessThan(0.005);
    expect(frameResidualDeg('pa')).toBeLessThan(0.005);
  });
});
